    "[id=8160] SourceFile=Linux_full.log Month=Nov Day=18 Time=5:00:36 Host=combo Component=kernel Out of Memory: Killed process 7252 (httpd)."
  ],
  "context_events": [
    "[id=8156] SourceFile=Linux_full.log Month=Nov Day=18 Time=4:05:07 Host=combo Component=su(pam_unix) PID=8240 session opened for user cyrus by (uid=0)",
    "[id=8157] SourceFile=Linux_full.log Month=Nov Day=18 Time=4:05:08 Host=combo Component=su(pam_unix) PID=8240 session closed for user cyrus"
  ],
  "analysis": {
    "fault_category": "memory",
    "affected_components": ["logrotate", "7250 (httpd)", "7252 (httpd)"],
    "recovery_state": "unknown",
    "likely_cause": "Memory exhaustion caused the httpd terminations; the cause of logrotate's abnormal exit is undetermined.",
    "evidence_ids": ["8158", "8159", "8160"]
  },
  "interpretation": "Logrotate failed before two out-of-memory kills of httpd processes. The logs do not show whether either service recovered."
}

